45	    const value = Number(amount);
46	    if (!(value > 0)) {
47	      setError('Amount must be greater than zero');
48	      return;
49	    }
50	    setError('');
51	    const res = await fetch(`/api/projects/${projectId}/invoices`, {
52	      method: 'POST',
