3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // project references client via FK; H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the duration of the clear, then restore it.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE task RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE line_item RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE invoice RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE project RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE contact RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE client RESTART IDENTITY");
44	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
45	    }
46	
47	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
48	    @PostMapping("/seed")
49	    @SuppressWarnings("unchecked")
50	    public void seed(@RequestBody Map<String, Object> fixture) {
51	        List<Map<String, Object>> clients =
52	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
53	        for (Map<String, Object> client : clients) {
54	            jdbc.update("INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
55	                    ((Number) client.get("id")).longValue(), client.get("name"), client.get("email"));
56	        }
57	        List<Map<String, Object>> projects =
58	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
59	        for (Map<String, Object> project : projects) {
60	            jdbc.update("INSERT INTO project (id, name, client_id) VALUES (?, ?, ?)",
61	                    ((Number) project.get("id")).longValue(), project.get("name"),
62	                    ((Number) project.get("clientId")).longValue());
63	        }
64	        List<Map<String, Object>> tasks =
65	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
66	        for (Map<String, Object> task : tasks) {
67	            Object done = task.getOrDefault("done", Boolean.FALSE);
68	            jdbc.update("INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
69	                    ((Number) task.get("id")).longValue(),
70	                    ((Number) task.get("projectId")).longValue(), task.get("title"),
71	                    Boolean.TRUE.equals(done));
72	        }
73	        List<Map<String, Object>> contacts =
74	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
75	        for (Map<String, Object> contact : contacts) {
76	            jdbc.update(
77	                    "INSERT INTO contact (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
78	                    ((Number) contact.get("id")).longValue(),
79	                    ((Number) contact.get("clientId")).longValue(), contact.get("name"),
80	                    contact.get("email"), contact.get("role"));
81	        }
82	        List<Map<String, Object>> invoices =
83	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
84	        for (Map<String, Object> invoice : invoices) {
85	            Object status = invoice.getOrDefault("status", "DRAFT");
86	            Object issuedDate = invoice.get("issuedDate");
87	            Object dueDate = invoice.get("dueDate");
88	            long invoiceId = ((Number) invoice.get("id")).longValue();
89	            // An invoice's amount is the sum of its line items (quantity times unit price); work it
90	            // out here so a fixture lists the things being charged for, not a pre-computed figure.
91	            // A fixture may still pass an explicit amount for an invoice with no line items.
92	            List<Map<String, Object>> lineItems =
93	                    (List<Map<String, Object>>) invoice.getOrDefault("lineItems", null);
94	            java.math.BigDecimal amount;
95	            if (lineItems != null) {
96	                amount = java.math.BigDecimal.ZERO;
97	                for (Map<String, Object> lineItem : lineItems) {
98	                    java.math.BigDecimal unitPrice =
99	                            new java.math.BigDecimal(lineItem.get("unitPrice").toString());
100	                    int qty = ((Number) lineItem.get("qty")).intValue();
101	                    amount = amount.add(unitPrice.multiply(java.math.BigDecimal.valueOf(qty)));
102	                }
